// Command openapi-export renders the OpenAPI document generated by the
// internal/rest Huma API and writes it to api/openapi.{yaml,json}. Huma code
// is the canonical contract; this command materializes it as a committed
// artifact for the Python/TS client generators and for drift detection
// (internal/rest/openapi_drift_test.go regenerates and diffs).
package main

import (
	"log"
	"os"
	"path/filepath"

	"github.com/go-chi/chi/v5"

	"github.com/sarathsp06/sparrow/internal/rest"
)

func main() {
	outDir := "api"
	if len(os.Args) > 1 {
		outDir = os.Args[1]
	}
	if err := os.MkdirAll(outDir, 0o755); err != nil {
		log.Fatalf("mkdir %s: %v", outDir, err)
	}

	// A nil service is fine: exporting the spec only walks operation/schema
	// registration, it never invokes a handler.
	api := rest.Mount(chi.NewRouter(), nil)

	yamlBytes, err := api.OpenAPI().YAML()
	if err != nil {
		log.Fatalf("render yaml: %v", err)
	}
	if err := os.WriteFile(filepath.Join(outDir, "openapi.yaml"), yamlBytes, 0o644); err != nil {
		log.Fatalf("write openapi.yaml: %v", err)
	}

	jsonDoc, err := api.OpenAPI().MarshalJSON()
	if err != nil {
		log.Fatalf("render json: %v", err)
	}
	if err := os.WriteFile(filepath.Join(outDir, "openapi.json"), jsonDoc, 0o644); err != nil {
		log.Fatalf("write openapi.json: %v", err)
	}

	log.Printf("wrote %s/openapi.{yaml,json}", outDir)
}
